import codecs, hashlib, json, struct, sys, unicodedata
assert sys.version_info[:3] == (3,14,7)
assert unicodedata.unidata_version == '16.0.0'
result = {'version':sys.version,'unicode':unicodedata.unidata_version}
for name, inputs in (
    ('pairs',(bytes((a,b)) for a in range(128,256) for b in range(256))),
    ('four',(bytes((a,b,c,d)) for a in range(129,255) for b in range(48,58) for c in range(129,255) for d in range(48,58))),
):
    h=hashlib.sha256(); count=0; total=0
    for data in inputs:
        total+=1
        try:
            text=data.decode('gb18030')
            assert len(text)==1
            point=ord(text); count+=1
        except UnicodeDecodeError:
            point=-1
        h.update(struct.pack('<i',point))
    result[name]={'count':count,'total':total,'sha256':h.hexdigest()}
h=hashlib.sha256(); count=0
for point in range(0x110000):
    try:
        data=chr(point).encode('gb18030'); count+=1
        number=int.from_bytes(data,'big')
    except UnicodeEncodeError:
        number=-1
    h.update(struct.pack('<q',number))
result['encode']={'count':count,'total':0x110000,'sha256':h.hexdigest()}
print(json.dumps(result,indent=2))

