import codecs,hashlib,json

def record(h,row): h.update((json.dumps(row,separators=(',',':'),ensure_ascii=True)+'\n').encode())

def corpus():
    for a in range(128,256):
        for b in range(256): yield bytes((a,b))
    for a in (128,129,132,133,143,144,227,228,254,255):
        for b in (47,48,49,57,58):
            for c in (0,128,129,254,255):
                for d in range(256): yield bytes((a,b,c,d))
    for data in (b'\x81',b'\x81\x30',b'\x81\x30\x81',b'\xff\x30',b'\xff\x30\xff'):
        yield data
for policy in ('strict','ignore','replace'):
    h=hashlib.sha256();count=0
    for data in corpus():
        count+=1
        try:
            text,n=codecs.getdecoder('gb18030')(data,policy)
            row=['ok',list(map(ord,text)),n]
        except UnicodeDecodeError as e: row=['error',e.start,e.end,e.reason]
        record(h,row)
    print(policy,count,h.hexdigest())
for policy in ('ignore','replace'):
    data=''.join(map(chr,range(0x110000))).encode('gb18030',policy)
    print('encode',policy,len(data),hashlib.sha256(data).hexdigest())
for policy in ('strict','ignore','replace'):
    h=hashlib.sha256();count=0
    for data in (b'A\x81\x30\x81\x30\xd6\xd0\x90\x30\x81\x30Z',b'\xff\x30\xff',b'\x81\x30\x81',b'\x84\x31\xa5\x30',b'\xffA',b'\xe3\x32\x9a\x36'):
        for split in range(len(data)+1):
            count+=1
            decoder=codecs.getincrementaldecoder('gb18030')(policy)
            row=[]
            for chunk,final in ((data[:split],False),(data[split:],True)):
                try: row.append(['ok',list(map(ord,decoder.decode(chunk,final)))])
                except UnicodeDecodeError as e: row.append(['error',list(e.object),e.start,e.end,e.reason])
                pending,state=decoder.getstate();row.append([list(pending),state])
            record(h,row)
    print('incremental',policy,count,h.hexdigest())

