import codecs, hashlib, json
originals=['','A','😀']
pendings=['','Z','12345678']
actions=['end','negative','rewind','out-of-bounds','overflow','raise','reset','nested','nested-failure','policy']
def state(text,opaque):
    b=text.encode('utf-8'); return int.from_bytes(bytes([len(b)])+b+opaque.to_bytes(8,'little'),'little')
def describe(e,failure):
    if isinstance(e,UnicodeEncodeError): return ['error',type(e).__name__,e.encoding,list(map(ord,e.object)),e.start,e.end,e.reason]
    return ['error',type(e).__name__,str(e),e is failure]
for name in ['gb18030']:
    rows=[]
    for original in originals:
      for pending in pendings:
       for final in [False,True]:
        for action in actions:
         for replacement in ['bytes','text','invalid']:
          seen=[]; count=[0]; failure=ValueError('guest failure')
          encoder=codecs.getincrementalencoder(name)('encoder_matrix')
          retained_policy=encoder.errors
          def handler(error):
            count[0]+=1
            seen.append([error.encoding,list(map(ord,error.object)),error.start,error.end,error.reason])
            encoder.setstate(state(pending,99))
            if action=='raise': raise failure
            if action=='reset': encoder.reset()
            if action=='policy': encoder.errors='ignore'
            if action in ('nested','nested-failure'):
              encoder.setstate(state('X',123))
              if action=='nested-failure': encoder.errors='strict'
              try: result=['ok',list(encoder.encode('Y' if action=='nested' else '\ud800',False))]
              except BaseException as e: result=describe(e,failure)
              encoder.errors='encoder_matrix'
              seen.append(['nested',result,str(encoder.getstate())])
            position=error.end
            if action=='negative' and position<len(error.object): position-=len(error.object)
            if action=='rewind' and count[0]==1: position=0
            if action=='out-of-bounds': position=len(error.object)+1
            if action=='overflow': position=1<<63
            return (b'\x80\xff' if replacement=='bytes' else '中' if replacement=='text' else '\ud800',position)
          codecs.register_error('encoder_matrix',handler)
          encoder.setstate(state(original,42))
          try: result=['ok',list(encoder.encode('\ud800A\udfff',final))]
          except BaseException as e: result=describe(e,failure)
          rows.append([list(map(ord,original)),list(map(ord,pending)),final,action,replacement,seen,result,str(encoder.getstate())])
    data=''.join(json.dumps(row,separators=(',',':'),ensure_ascii=True)+'\n' for row in rows)
    print(name,len(rows),hashlib.sha256(data.encode()).hexdigest(),flush=True)
    with open('/tmp/safe-python-encoder-matrix-'+name+'.json','w') as f: json.dump(rows,f)
